package com.codepilot1c.core.tools.development;
import java.util.*;import java.util.concurrent.CompletableFuture;import com.google.gson.Gson;import com.codepilot1c.core.tools.*;import com.codepilot1c.core.edt.infobase.NativeUpdateInteraction;import com.codepilot1c.core.tools.workspace.BackgroundJobRegistry;import com.codepilot1c.core.mcp.host.*;
@ToolMeta(name="edt_update_control",category="qa",mutating=true,tags={"workspace","edt","sensitive"})
public final class EdtUpdateControlTool extends AbstractTool {
 public String getDescription(){return "Inspect/continue an existing Bridge-owned native update waiting for exclusive infobase access or an application-update decision during an owned debug launch. A decision object exposes typed choices and exact command payloads for the agent; default ask the user, task-scoped authorization can permit updates. list(project), status(update_id) show original job/base UUID, recognized native question hash and blocker session descriptions. retry or cancel requires expected_question_sha256; answers only the exact owned native exclusive-lock question. No new update is started and dynamic update is never selected. close_owned_and_retry additionally requires owner ui_run_id and its fresh expected_cleanup_sha256: only same-base owned UI client can be cleaned; active/unknown/uncollected task guards remain. Other/user sessions require the user to close them. No arbitrary PID, generic dialogs, security/trust answers or force termination of user processes. An unknown/restarted scope cannot be replayed. Retry may wait again; inspect same update/job and final native EQUAL separately.";}
 public String getParameterSchema(){return """
 {"type":"object","additionalProperties":false,"required":["action"],"properties":{"action":{"enum":["list","status","retry","cancel","update_and_launch","close_owned_and_retry"]},"project":{"type":"string"},"update_id":{"type":"string","pattern":"^upd-[a-f0-9-]{36}$"},"expected_question_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"},"ui_run_id":{"type":"string"},"expected_cleanup_sha256":{"type":"string","pattern":"^[a-f0-9]{64}$"}}}
 """;}
 protected CompletableFuture<ToolResult> doExecute(ToolParameters p){try{String action=p.requireString("action");var keys=new HashSet<>(p.getRaw().keySet());keys.remove("action");Set<String> fields=switch(action){case "list"->Set.of("project");case "status"->Set.of("update_id");case "retry","cancel","update_and_launch"->Set.of("update_id","expected_question_sha256");case "close_owned_and_retry"->Set.of("update_id","expected_question_sha256","ui_run_id","expected_cleanup_sha256");default->throw new IllegalArgumentException("Unknown action");};if(!keys.equals(fields))throw new IllegalArgumentException("Exact action fields required");if(action.equals("list"))return CompletableFuture.completedFuture(ToolResult.success(new Gson().toJson(NativeUpdateInteraction.list(p.requireString("project")))));if(action.equals("status"))return CompletableFuture.supplyAsync(()->{try{return ToolResult.success(new Gson().toJson(NativeUpdateInteraction.status(p.requireString("update_id"))));}catch(Exception e){return ToolResult.failure(e.getMessage());}});if(action.equals("update_and_launch")&&!new DefaultMcpToolExposurePolicy(McpHostConfigStore.getInstance().load()).isExposed("edt_infobase_refresh"))throw new IllegalStateException("Database update operation not exposed");if(action.equals("close_owned_and_retry")){var cfg=McpHostConfigStore.getInstance().load();var policy=new DefaultMcpToolExposurePolicy(cfg);for(String tool:com.codepilot1c.core.edt.development.UiRunBackend.dependencies())if(!policy.isExposed(tool))throw new IllegalStateException("Owned UI cleanup dependency unavailable");if(!policy.isExposed("edt_ui_run"))throw new IllegalStateException("Owned UI cleanup unavailable");}String job=BackgroundJobRegistry.getInstance().startJob("update-wait-control",()->new Gson().toJson(action.equals("close_owned_and_retry")?NativeUpdateInteraction.closeOwnedAndRetry(p.requireString("update_id"),p.requireString("expected_question_sha256"),p.requireString("ui_run_id"),p.requireString("expected_cleanup_sha256")):NativeUpdateInteraction.answer(p.requireString("update_id"),p.requireString("expected_question_sha256"),action)));return CompletableFuture.completedFuture(ToolResult.success(new Gson().toJson(Map.of("job_id",job,"next_tool","edt_operation_status","new_update_dispatched",false))));}catch(Exception e){return CompletableFuture.completedFuture(ToolResult.failure("EDT_UPDATE_CONTROL: "+e.getMessage()));}}
}
